//! The measured tables the layout reads, from `data.json` (generated by `generate.mjs` from
//! `design-font-metrics.mjs`, `design-font-catalog.mjs`, `design-font-characters.mjs` and `design-color-names.mjs`).
//! Parsed once, on first use.

use std::collections::HashMap;
use std::sync::OnceLock;

use serde_json::Value;

/// Advances (in ems) of one family: 95 printable ASCII advances per weight, and measured extras by code point.
#[derive(Debug, Default)]
pub struct Family {
    /// Weights in ascending order, as `Object.keys` lists numeric keys.
    pub weights: Vec<(u32, Vec<f64>)>,
    pub extra: HashMap<u32, HashMap<u32, f64>>,
}

#[derive(Debug, Default)]
pub struct Tables {
    pub sans: Family,
    pub serif: Family,
    pub times: Family,
    pub mono: Family,
    pub inter: Family,
    /// By lower-case family name.
    pub catalog: HashMap<String, Family>,
    /// `(from, to, base)`: characters whose NFD base (marks removed) changes their fallback advance. `base` is the
    /// ASCII base, -1 when only marks remain, or a stand-in on the base's side of U+2E80 (0x2E80 or 0xA0).
    pub bases: Vec<(u32, u32, i64)>,
    /// `(from, to)`: the combining marks (`\p{M}`).
    pub marks: Vec<(u32, u32)>,
    pub colors: HashMap<String, [f64; 3]>,
}

const DATA: &str = include_str!("data.json");

pub fn tables() -> &'static Tables {
    static TABLES: OnceLock<Tables> = OnceLock::new();
    TABLES.get_or_init(|| parse(DATA))
}

fn advances(value: &Value) -> Vec<f64> {
    value.as_array().map(|list| list.iter().filter_map(Value::as_f64).collect()).unwrap_or_default()
}

fn sorted_weights(object: &serde_json::Map<String, Value>) -> Vec<(u32, Vec<f64>)> {
    let mut weights: Vec<(u32, Vec<f64>)> =
        object.iter().filter_map(|(key, value)| Some((key.parse::<u32>().ok()?, advances(value)))).collect();
    weights.sort_by_key(|(weight, _)| *weight);
    weights
}

fn measured(value: &Value) -> Family {
    let Some(object) = value.as_object() else { return Family::default() };
    let extra = object
        .get("extra")
        .and_then(Value::as_object)
        .map(|by_weight| {
            by_weight
                .iter()
                .filter_map(|(weight, points)| {
                    let points = points
                        .as_object()?
                        .iter()
                        .filter_map(|(point, advance)| Some((point.parse::<u32>().ok()?, advance.as_f64()?)))
                        .collect();
                    Some((weight.parse::<u32>().ok()?, points))
                })
                .collect()
        })
        .unwrap_or_default();
    Family { weights: sorted_weights(object), extra }
}

/// `catalogTable`: a catalog family's first 95 advances per weight, the rest by the extra characters' code points.
fn catalog(value: &Value, extra_points: &[u32]) -> Family {
    let Some(advances_by_weight) = value.get("advances").and_then(Value::as_object) else { return Family::default() };
    let all = sorted_weights(advances_by_weight);
    let mut family = Family::default();
    for (weight, advances) in all {
        let extra = extra_points.iter().enumerate().filter_map(|(index, point)| Some((*point, *advances.get(95 + index)?))).collect();
        family.extra.insert(weight, extra);
        family.weights.push((weight, advances.into_iter().take(95).collect()));
    }
    family
}

fn ranges(value: &Value) -> Vec<Vec<i64>> {
    value
        .as_array()
        .map(|list| list.iter().filter_map(|r| r.as_array().map(|r| r.iter().filter_map(Value::as_i64).collect())).collect())
        .unwrap_or_default()
}

/// The entry of sorted, disjoint `(from, to, ..)` ranges that holds `point`.
pub fn find_range<T: Copy>(ranges: &[T], point: u32, bounds: impl Fn(&T) -> (u32, u32)) -> Option<T> {
    let index = ranges.partition_point(|range| bounds(range).1 < point);
    ranges.get(index).copied().filter(|range| bounds(range).0 <= point)
}

fn parse(json: &str) -> Tables {
    let root: Value = serde_json::from_str(json).expect("data.json is valid JSON");
    let metrics = &root["metrics"];
    let extra_points: Vec<u32> =
        root["extra"].as_array().map(|a| a.iter().filter_map(|v| v.as_u64().map(|v| v as u32)).collect()).unwrap_or_default();
    Tables {
        sans: measured(&metrics["sans"]),
        serif: measured(&metrics["serif"]),
        times: measured(&metrics["times"]),
        mono: measured(&metrics["mono"]),
        inter: measured(&metrics["inter"]),
        catalog: root["catalog"]
            .as_object()
            .map(|entries| entries.iter().map(|(key, entry)| (key.clone(), catalog(entry, &extra_points))).collect())
            .unwrap_or_default(),
        bases: ranges(&root["bases"]).into_iter().map(|r| (r[0] as u32, r[1] as u32, r[2])).collect(),
        marks: ranges(&root["marks"]).into_iter().map(|r| (r[0] as u32, r[1] as u32)).collect(),
        colors: root["colors"]
            .as_object()
            .map(|m| {
                m.iter()
                    .filter_map(|(name, rgb)| {
                        let rgb = rgb.as_array()?;
                        Some((name.clone(), [rgb.first()?.as_f64()?, rgb.get(1)?.as_f64()?, rgb.get(2)?.as_f64()?]))
                    })
                    .collect()
            })
            .unwrap_or_default(),
    }
}
